filename = sprintf('Log_%s_block_%d.mat', subject, session);
save([pth filename], 'rating');


session=session+1;
trial = sprintf('Session \n\n     %d',session);
if session == 8
Screen('FillRect', window, 240);
DrawFormattedText(window, break_text, 'center', 'center', 0);
% IOPort('Write',h,'t');WaitSecs(0.01);% IOPort('Write',h,'t'); 
Screen('Flip', window);
KbPressWait();
else
Screen('FillRect', window, 240);
DrawFormattedText(window, wait_text, 'center', 'center', 0);
% IOPort('Write',h,'t');WaitSecs(0.01);% IOPort('Write',h,'t'); 
Screen('Flip', window);
KbPressWait();
end
Screen('FillRect', window, 100);
% Screen(window,'FillRect',[100,100,100],[100,200,300,500]);
% Screen('DrawText', window, 'Practice', 150, 350, [0 0 0]);
Screen(window,'FillRect',130,p1);
DrawFormattedText(window, trial,p1(1)+50,p1(2)+100,[0,0,0]);
Screen(window,'FillRect',130,p3);
Screen('DrawText', window, 'Abort', p3(1)+50, p3(2)+100, [0 0 0]);
%if session == 8
    %DrawFormattedText(window, break_text, 'center', (height/2)-250, 0);
%end
Screen('Flip',window);

switch ind

case 451
introText = 'Thank You For Your Time and Contribution Towards Science.\n\n We truly appreciate your participation!\n\n Press Esc to exit';
Screen('FillRect', window, 100);
DrawFormattedText(window, introText, 'center', 'center', 0);
Screen('Flip', window);
    % Wait for keystroke:
    [~, keycode] = KbStrokeWait;
    % Escape exits:
    if keycode(escape)
        Screen('CloseAll');
        ShowCursor;
%         Screen('Preference', 'Verbosity', oldVerbosityLevel);
%         Screen('Preference', 'VisualDebugLevel', oldVisualDebugLevel);
    end
otherwise 

while 1
while buttons(1) %if already pressed, wait for release
            [x, y, buttons] = GetMouse;
end
        while ~buttons(1) %wait for press
            [x, y, buttons] = GetMouse;
        end
        while buttons(1) %wait for release
            [x, y, buttons] = GetMouse;
 
        end

  
   if  IsInRect(x,y,p1)
%       Screen('CloseAll');
      close all;
      ShowCursor; 
%       session=session+1;
      face_exp_new(subject,window,screenNumber,width,height,session,pth,p1,p2,p3,ind,Index_Matrix,h);
%       Screen('Preference', 'Verbosity', oldVerbosityLevel);
%       Screen('Preference', 'VisualDebugLevel', oldVisualDebugLevel);
      break;
      
   end
  
  if  IsInRect(x,y,p3)
      Screen('CloseAll');
      ShowCursor;
%       Screen('Preference', 'Verbosity', oldVerbosityLevel);
%       Screen('Preference', 'VisualDebugLevel', oldVisualDebugLevel);
      break;
      
  end

end
end
    
catch
	Screen('CloseAll');
	ShowCursor;
%     Screen('Preference', 'Verbosity', oldVerbosityLevel);
%     Screen('Preference', 'VisualDebugLevel', oldVisualDebugLevel);
	psychrethrow(psychlasterror);
end
end